--
-- Table structure for table `alumni_pt`
--

CREATE TABLE `alumni_pt` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `murid_id` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'nullable: alumni lama yang input manual & belum ada di Data Murid',
  `nama_lengkap` varchar(150) NOT NULL,
  `kelas` varchar(20) DEFAULT NULL COMMENT 'kelas terakhir saat lulus',
  `strata_pendidikan` enum('D3','D4','S1') DEFAULT NULL,
  `program_studi` varchar(150) DEFAULT NULL,
  `nama_perguruan_tinggi` varchar(200) DEFAULT NULL,
  `jenis_perguruan_tinggi` enum('Negeri','Swasta','Kedinasan','Luar Negeri') NOT NULL DEFAULT 'Negeri',
  `jalur_masuk` enum('SNBP','SNBT','PMDP','SIMAMA','SIMAMI','UM PTKIN','ADIK','Mandiri','Tes Kedinasan','Reguler','Undangan','Lainnya') NOT NULL,
  `pilihan_ke` tinyint(3) UNSIGNED DEFAULT NULL,
  `nilai_rapor` decimal(5,2) DEFAULT NULL COMMENT 'diisi jika jalur pakai nilai rapor',
  `skor_utbk` decimal(6,2) DEFAULT NULL COMMENT 'diisi jika jalur pakai skor UTBK',
  `kontak_wa` varchar(20) DEFAULT NULL,
  `pelamar_kipk` tinyint(1) DEFAULT NULL,
  `tahun_ajaran` varchar(9) DEFAULT NULL,
  `created_by` bigint(20) UNSIGNED DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

