--
-- Table structure for table `asesmen_karakteristik`
--

CREATE TABLE `asesmen_karakteristik` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `murid_id` bigint(20) UNSIGNED NOT NULL,
  `tanggal_asesmen` date NOT NULL,
  `gaya_belajar` varchar(30) DEFAULT NULL COMMENT 'Visual/Auditori/Kinestetik, bisa kombinasi mis. "KV"',
  `tipe_kepribadian` varchar(30) DEFAULT NULL COMMENT 'Melankolis/Plegmatis/Koleris/Sanguinis (data mentah kadang campuran)',
  `mapel_favorit` varchar(150) DEFAULT NULL,
  `riasec` varchar(20) DEFAULT NULL COMMENT 'urutan tipe bakat, misal "A S E"',
  `kelas_peminatan_pilihan` varchar(30) DEFAULT NULL COMMENT 'preferensi kelas X peminatan (raw dari spreadsheet BK)',
  `prospek_profil_diri` text DEFAULT NULL,
  `iq` smallint(5) UNSIGNED DEFAULT NULL,
  `created_by` bigint(20) UNSIGNED DEFAULT NULL COMMENT 'user (admin) yang menginput',
  `created_at` datetime NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

