--
-- Table structure for table `basis_data_beasiswa`
--

CREATE TABLE `basis_data_beasiswa` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `nama_beasiswa` varchar(150) NOT NULL,
  `durasi_tahun` decimal(3,1) DEFAULT NULL COMMENT 'dalam tahun/semester',
  `periode_apply` varchar(150) DEFAULT NULL COMMENT 'perkiraan bulan/rentang waktu pendaftaran',
  `jenjang_berlaku` set('SMA','Kuliah') NOT NULL DEFAULT 'SMA,Kuliah',
  `status` enum('Aktif','Diarsipkan') NOT NULL DEFAULT 'Aktif',
  `created_by` bigint(20) UNSIGNED DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

