-- --------------------------------------------------------

--
-- Table structure for table `murid`
--

CREATE TABLE `murid` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `nisn` varchar(20) NOT NULL,
  `nama_lengkap` varchar(150) NOT NULL,
  `nama_panggilan` varchar(50) DEFAULT NULL,
  `jenis_kelamin` enum('L','P') DEFAULT NULL,
  `kelas` varchar(20) DEFAULT NULL COMMENT 'kelas saat ini, histori di murid_kelas_histori',
  `angkatan` varchar(9) DEFAULT NULL COMMENT 'tahun ajaran masuk, misal 2023/2024',
  `tempat_lahir` varchar(100) DEFAULT NULL,
  `tanggal_lahir` date DEFAULT NULL,
  `agama` varchar(20) DEFAULT NULL,
  `golongan_darah` enum('A','B','AB','O','Tidak Diketahui') DEFAULT NULL,
  `alamat_rumah` text DEFAULT NULL,
  `tinggal_bersama` enum('Orang Tua','Wali','Saudara','Lainnya') DEFAULT NULL,
  `anak_ke` tinyint(3) UNSIGNED DEFAULT NULL,
  `hobi` varchar(255) DEFAULT NULL,
  `cita_cita` varchar(255) DEFAULT NULL,
  `warna_favorit` varchar(50) DEFAULT NULL,
  `makanan_favorit` varchar(100) DEFAULT NULL,
  `bahasa_keseharian` varchar(50) DEFAULT NULL,
  `permainan_online` varchar(100) DEFAULT NULL,
  `permainan_offline` varchar(100) DEFAULT NULL,
  `no_wa` varchar(20) DEFAULT NULL,
  `akun_sosial` varchar(150) DEFAULT NULL,
  `status` enum('Aktif','Lulus','Pindah','Keluar') NOT NULL DEFAULT 'Aktif',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

